export const responseSchemas = {
  "/playlist/detail": PlaylistResponseSchema,
  "/playlist/track/all": SongsResponseSchema,
  "/user/playlist": UserPlaylistsResponseSchema,
  "/lyric/new": WebLyricsResponseSchema,
  "/lyric/ttml": z.union([TtmlFoundSchema, TtmlMissingSchema]),
  "/song/url/v1": PlaybackResponseSchema,
  "/album": AlbumResponseSchema,
  "/mv/detail": VideoResponseSchema,
  "/mv/url": VideoUrlResponseSchema,
  "/artists": z.union([ArtistHotSongsResponseSchema, LegacyErrorResponseSchema]),
  "/artist/detail": ArtistDetailResponseSchema,
  "/artist/album": z.union([ArtistAlbumsResponseSchema, LegacyErrorResponseSchema]),
  "/artist/mv": z.union([ArtistVideosResponseSchema, LegacyErrorResponseSchema]),
  "/artist/songs": z.union([ArtistSongsResponseSchema, LegacyErrorResponseSchema]),
  "/cloudsearch": SearchResponseSchema,
  "/search/hot/detail": z.union([HotSearchResponseSchema, LegacyErrorResponseSchema]),
  "/search/suggest": z.union([SuggestResponseSchema, LegacyErrorResponseSchema]),
  "/extra/music/url": z.array(QmcSongDetailSchema),
  "/extra/music/info": QmcSongDetailsSchema,
  "/extra/music/comments": QmcCommentsResponseSchema,
} as const;
export type ApiPath = keyof typeof responseSchemas;
export type ApiResponseFor<P extends ApiPath> = z.infer<(typeof responseSchemas)[P]>;
